import React, { useState, useEffect, useMemo } from 'react';
import { Plus, Search, Filter, Save, Star, X, Calendar, Tag, Layout, BarChart3, List } from "lucide-react";

interface Task {
  id: number;
  title: string;
  description: string;
  status: string;
  priority: string;
  tags: string;
  project_id: number;
  project_name: string;
  created_at: string;
  due_date?: string;
}

interface SavedView {
  id: number;
  name: string;
  filters: {
    search?: string;
    tags?: string;
    date_from?: string;
    date_to?: string;
    quick_filter?: string;
  };
  is_default: boolean;
}

const Tasks: React.FC = () => {
  // 原有状态
  const [tasks, setTasks] = useState<Task[]>([]);
  const [projects, setProjects] = useState<any[]>([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [projectFilter, setProjectFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  
  // 新增筛选状态
  const [search, setSearch] = useState('');
  const [tags, setTags] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [quickFilter, setQuickFilter] = useState('');
  const [savedViews, setSavedViews] = useState<SavedView[]>([]);
  const [showFilters, setShowFilters] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize] = useState(50);
  const [showSaveViewModal, setShowSaveViewModal] = useState(false);
  const [viewName, setViewName] = useState('');
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [viewMode, setViewMode] = useState("list");
  
  // 防抖搜索
  const [debouncedSearch, setDebouncedSearch] = useState('');
  
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search);
    }, 300);
    return () => clearTimeout(timer);
  }, [search]);

  // 获取保存的视图
  const fetchSavedViews = async () => {
    try {
      const res = await fetch('/api/saved-views');
      const data = await res.json();
      if (data.success) {
        setSavedViews(data.views);
      }
    } catch (error) {
      console.error('Failed to fetch saved views:', error);
    }
  };

  // 获取任务
  const fetchTasks = async () => {
    try {
      const params = new URLSearchParams();
      if (debouncedSearch) params.append('search', debouncedSearch);
      if (tags) params.append('tags', tags);
      if (dateFrom) params.append('date_from', dateFrom);
      if (dateTo) params.append('date_to', dateTo);
      if (quickFilter) params.append('quick_filter', quickFilter);
      if (projectFilter) params.append('project_id', projectFilter);
      if (statusFilter) params.append('status', statusFilter);
      
      params.append('per_page', '2000');
      const res = await fetch(`/api/tasks?${params}`);
      const data = await res.json();
      if (data.success) {
        setTasks(data.tasks);
      }
    } catch (error) {
      console.error('Failed to fetch tasks:', error);
    }
  };

  // 获取项目
  const fetchProjects = async () => {
    try {
      const res = await fetch('/api/projects');
      const data = await res.json();
      if (data.success) {
        setProjects(data.projects);
      }
    } catch (error) {
      console.error('Failed to fetch projects:', error);
    }
  };

  useEffect(() => {
    fetchTasks();
    fetchProjects();
    fetchSavedViews();
  }, [debouncedSearch, tags, dateFrom, dateTo, quickFilter, projectFilter, statusFilter]);

  // 保存视图
  const handleSaveView = async () => {
    if (!viewName.trim()) {
      alert('请输入视图名称');
      return;
    }
    
    try {
      const filters: any = {};
      if (debouncedSearch) filters.search = debouncedSearch;
      if (tags) filters.tags = tags;
      if (dateFrom) filters.date_from = dateFrom;
      if (dateTo) filters.date_to = dateTo;
      if (quickFilter) filters.quick_filter = quickFilter;
      if (projectFilter) filters.project_id = projectFilter;
      if (statusFilter) filters.status = statusFilter;
      
      const res = await fetch('/api/saved-views', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: viewName, filters })
      });
      
      const data = await res.json();
      if (data.success) {
        alert('视图已保存');
        setViewName('');
        setShowSaveViewModal(false);
        fetchSavedViews();
      }
    } catch (error) {
      console.error('Failed to save view:', error);
      alert('保存失败');
    }
  };

  // 加载视图
  const loadView = (view: SavedView) => {
    const f = view.filters;
    setSearch(f.search || '');
    setTags(f.tags || '');
    setDateFrom(f.date_from || '');
    setDateTo(f.date_to || '');
    setQuickFilter(f.quick_filter || '');
    setProjectFilter((f as any).project_id || '');
    setStatusFilter((f as any).status || '');
  };

  // 删除视图
  const deleteView = async (viewId: number) => {
    if (!confirm('确定要删除这个视图吗？')) return;
    
    try {
      const res = await fetch(`/api/saved-views/${viewId}`, { method: 'DELETE' });
      const data = await res.json();
      if (data.success) {
        fetchSavedViews();
      } else {
        alert(data.error || '删除失败');
      }
    } catch (error) {
      console.error('Failed to delete view:', error);
      alert('删除失败');
    }
  };

  // 清除筛选
  const clearFilters = () => {
    setSearch('');
    setTags('');
    setDateFrom('');
    setDateTo('');
    setQuickFilter('');
    setProjectFilter('');
    setStatusFilter('');
  };

  // 计算激活的筛选条件
  const activeFilters = useMemo(() => {
    const filters = [];
    if (debouncedSearch) filters.push({ type: 'search', label: `搜索：${debouncedSearch}` });
    if (tags) filters.push({ type: 'tags', label: `标签：${tags}` });
    if (quickFilter) {
      const labels: any = { today: '今天', this_week: '本周', this_month: '本月' };
      filters.push({ type: 'quick', label: labels[quickFilter] || quickFilter });
    }
    if (dateFrom || dateTo) {
      filters.push({ type: 'date', label: `${dateFrom || '...'} ~ ${dateTo || '...'}` });
    }
    return filters;
  }, [debouncedSearch, tags, quickFilter, dateFrom, dateTo]);

  return (
    <div className="p-6 max-w-7xl mx-auto">
      {/* 头部 */}
      <div className="mb-6">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-3xl font-bold text-gray-900">任务管理</h1>
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            <Plus size={20} />
            新建任务
          </button>
        </div>

        {/* 搜索和筛选工具栏 */}
        <div className="flex flex-wrap gap-3 items-center">
          {/* 搜索框 */}
          <div className="relative flex-1 min-w-[300px]">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" size={20} />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="搜索任务标题、描述、标签..."
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
            {search && (
              <button
                onClick={() => setSearch('')}
                className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                <X size={16} />
              </button>
            )}
          </div>

          {/* 保存视图按钮 */}
          <button
            onClick={() => setShowSaveViewModal(true)}
            className="flex items-center gap-2 px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            <Save size={18} />
            保存视图
          </button>

          {/* 筛选按钮 */}
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`flex items-center gap-2 px-4 py-2 border rounded-lg ${
              showFilters ? 'bg-blue-50 border-blue-500' : 'border-gray-300 hover:bg-gray-50'
            }`}
          >
            <Filter size={18} />
            筛选
          </button>
        </div>

        {/* 激活的筛选条件 */}
        {activeFilters.length > 0 && (
          <div className="flex flex-wrap gap-2 mt-3">
            {activeFilters.map((filter, idx) => (
              <span
                key={idx}
                className="inline-flex items-center gap-1 px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm"
              >
                {filter.label}
                <button
                  onClick={() => {
                    if (filter.type === 'search') setSearch('');
                    else if (filter.type === 'tags') setTags('');
                    else if (filter.type === 'quick') setQuickFilter('');
                    else if (filter.type === 'date') { setDateFrom(''); setDateTo(''); }
                  }}
                  className="hover:text-blue-600"
                >
                  <X size={14} />
                </button>
              </span>
            ))}
            <button
              onClick={clearFilters}
              className="text-sm text-gray-500 hover:text-gray-700 underline"
            >
              清除所有
            </button>
          </div>
        )}

        {/* 高级筛选面板 */}
        {showFilters && (
          <div className="mt-4 p-4 bg-gray-50 rounded-lg border border-gray-200">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              {/* 标签筛选 */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  <Tag size={16} className="inline mr-1" />
                  标签
                </label>
                <input
                  type="text"
                  value={tags}
                  onChange={(e) => setTags(e.target.value)}
                  placeholder="多个标签用逗号分隔"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
              </div>

              {/* 快捷筛选 */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  <Calendar size={16} className="inline mr-1" />
                  时间范围
                </label>
                <div className="flex gap-2">
                  <button
                    onClick={() => setQuickFilter(quickFilter === 'today' ? '' : 'today')}
                    className={`flex-1 px-3 py-2 rounded-lg border ${
                      quickFilter === 'today'
                        ? 'bg-blue-600 text-white border-blue-600'
                        : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                    }`}
                  >
                    今天
                  </button>
                  <button
                    onClick={() => setQuickFilter(quickFilter === 'this_week' ? '' : 'this_week')}
                    className={`flex-1 px-3 py-2 rounded-lg border ${
                      quickFilter === 'this_week'
                        ? 'bg-blue-600 text-white border-blue-600'
                        : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                    }`}
                  >
                    本周
                  </button>
                  <button
                    onClick={() => setQuickFilter(quickFilter === 'this_month' ? '' : 'this_month')}
                    className={`flex-1 px-3 py-2 rounded-lg border ${
                      quickFilter === 'this_month'
                        ? 'bg-blue-600 text-white border-blue-600'
                        : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                    }`}
                  >
                    本月
                  </button>
                </div>
              </div>

              {/* 自定义日期范围 */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  自定义日期范围
                </label>
                <div className="flex gap-2">
                  <input
                    type="date"
                    value={dateFrom}
                    onChange={(e) => setDateFrom(e.target.value)}
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                  <span className="text-gray-500">~</span>
                  <input
                    type="date"
                    value={dateTo}
                    onChange={(e) => setDateTo(e.target.value)}
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 保存的视图快捷方式 */}
        {savedViews.length > 0 && (
          <div className="mt-4 flex flex-wrap gap-2">
            {savedViews.map((view) => (
              <div
                key={view.id}
                className="inline-flex items-center gap-2 px-3 py-1.5 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 cursor-pointer group"
                onClick={() => loadView(view)}
              >
                {view.is_default && <Star size={14} className="text-yellow-500 fill-yellow-500" />}
                <span className="text-sm text-gray-700">{view.name}</span>
                {!view.is_default && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      deleteView(view.id);
                    }}
                    className="opacity-0 group-hover:opacity-100 text-red-500 hover:text-red-700"
                  >
                    <X size={14} />
                  </button>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 任务列表 */}
      <div className="bg-white rounded-lg shadow border border-gray-200">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-50 border-b border-gray-200">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  任务
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  项目
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  状态
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  优先级
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  标签
                </th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                  创建时间
                </th>
                <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                  操作
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {tasks.length === 0 ? (
                <tr>
                  <td colSpan={7} className="px-6 py-12 text-center text-gray-500">
                    <Search size={48} className="mx-auto mb-4 text-gray-300" />
                    <p>暂无任务</p>
                  </td>
                </tr>
              ) : (
                tasks.map((task) => (
                  <tr key={task.id} className="hover:bg-gray-50">
                    <td className="px-6 py-4">
                      <div>
                        <div className="text-sm font-medium text-gray-900">{task.title}</div>
                        {task.description && (
                          <div className="text-sm text-gray-500 max-w-md">
                            {task.description}
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm text-gray-900">{task.project_name || '-'}</span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs rounded-full ${
                        task.status === 'completed' ? 'bg-green-100 text-green-800' :
                        task.status === 'in_progress' ? 'bg-blue-100 text-blue-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {task.status === 'completed' ? '已完成' :
                         task.status === 'in_progress' ? '进行中' : '待处理'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 text-xs rounded-full ${
                        task.priority === 'high' ? 'bg-red-100 text-red-800' :
                        task.priority === 'medium' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {task.priority === 'high' ? '高' :
                         task.priority === 'medium' ? '中' : '低'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {task.tags ? (
                        <div className="flex flex-wrap gap-1">
                          {task.tags.split(',').map((tag, idx) => (
                            <span
                              key={idx}
                              className="px-2 py-0.5 bg-purple-100 text-purple-800 rounded text-xs"
                            >
                              {tag.trim()}
                            </span>
                          ))}
                        </div>
                      ) : (
                        <span className="text-gray-400">-</span>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {new Date(task.created_at).toLocaleDateString('zh-CN')}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      <button 
                        onClick={() => {
                          setEditingTask(task);
                          setShowEditModal(true);
                        }}
                        className="text-blue-600 hover:text-blue-900 mr-3"
                      >
                        编辑
                      </button>
                      <button 
                        onClick={async () => {
                          if (!confirm('确定要删除这个任务吗？')) return;
                          try {
                            const res = await fetch(`/api/tasks/${task.id}`, { method: 'DELETE' });
                            const data = await res.json();
                            if (data.success) {
                              fetchTasks();
                            } else {
                              alert(data.error || '删除失败');
                            }
                          } catch (error) {
                            console.error('Failed to delete task:', error);
                            alert('删除失败');
                          }
                        }}
                        className="text-red-600 hover:text-red-900"
                      >
                        删除
                      </button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 添加任务弹窗 */}
      {showAddModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl">
            <h3 className="text-lg font-bold mb-4">新建任务</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">任务标题</label>
                <input
                  type="text"
                  id="newTaskTitle"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="输入任务标题"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">任务描述</label>
                <textarea
                  id="newTaskDescription"
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="输入任务描述"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">所属项目</label>
                <select
                  id="newTaskProject"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">请选择项目</option>
                  {projects.map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">状态</label>
                <select
                  id="newTaskStatus"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="todo">待办</option>
                  <option value="in_progress">进行中</option>
                  <option value="completed">已完成</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">优先级</label>
                <select
                  id="newTaskPriority"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="low">低</option>
                  <option value="medium">中</option>
                  <option value="high">高</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">标签</label>
                <input
                  type="text"
                  id="newTaskTags"
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="多个标签用逗号分隔"
                />
              </div>
            </div>
            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={() => setShowAddModal(false)}
                className="px-4 py-2 text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                取消
              </button>
              <button
                onClick={async () => {
                  const title = (document.getElementById('newTaskTitle') as HTMLInputElement).value;
                  const description = (document.getElementById('newTaskDescription') as HTMLTextAreaElement).value;
                  const project_id = parseInt((document.getElementById('newTaskProject') as HTMLSelectElement).value);
                  const status = (document.getElementById('newTaskStatus') as HTMLSelectElement).value;
                  const priority = (document.getElementById('newTaskPriority') as HTMLSelectElement).value;
                  const tags = (document.getElementById('newTaskTags') as HTMLInputElement).value;
                  
                  if (!title.trim()) {
                    alert('请输入任务标题');
                    return;
                  }
                  if (!project_id) {
                    alert('请选择所属项目');
                    return;
                  }
                  
                  try {
                    const res = await fetch('/api/tasks', {
                      method: 'POST',
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify({ title, description, project_id, status, priority, tags })
                    });
                    const data = await res.json();
                    if (data.success) {
                      alert('任务创建成功');
                      setShowAddModal(false);
                      fetchTasks();
                    } else {
                      alert(data.error || '创建失败');
                    }
                  } catch (error) {
                    console.error('Failed to create task:', error);
                    alert('创建失败');
                  }
                }}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                创建
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 编辑任务弹窗 */}
      {showEditModal && editingTask && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl">
            <h3 className="text-lg font-bold mb-4">编辑任务</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">任务标题</label>
                <input
                  type="text"
                  id="editTaskTitle"
                  defaultValue={editingTask.title}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="输入任务标题"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">任务描述</label>
                <textarea
                  id="editTaskDescription"
                  rows={3}
                  defaultValue={editingTask.description || ''}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="输入任务描述"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">所属项目</label>
                <select
                  id="editTaskProject"
                  defaultValue={editingTask.project_id || ''}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">请选择项目</option>
                  {projects.map(p => (
                    <option key={p.id} value={p.id}>{p.name}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">状态</label>
                <select
                  id="editTaskStatus"
                  defaultValue={editingTask.status === 'completed' ? 'completed' : editingTask.status === 'in_progress' ? 'in_progress' : 'todo'}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="todo">待办</option>
                  <option value="in_progress">进行中</option>
                  <option value="completed">已完成</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">优先级</label>
                <select
                  id="editTaskPriority"
                  defaultValue={editingTask.priority || 'medium'}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                >
                  <option value="low">低</option>
                  <option value="medium">中</option>
                  <option value="high">高</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">标签</label>
                <input
                  type="text"
                  id="editTaskTags"
                  defaultValue={editingTask.tags || ''}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  placeholder="多个标签用逗号分隔"
                />
              </div>
            </div>
            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={() => {
                  setShowEditModal(false);
                  setEditingTask(null);
                }}
                className="px-4 py-2 text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                取消
              </button>
              <button
                onClick={async () => {
                  const title = (document.getElementById('editTaskTitle') as HTMLInputElement).value;
                  const description = (document.getElementById('editTaskDescription') as HTMLTextAreaElement).value;
                  const project_id = parseInt((document.getElementById('editTaskProject') as HTMLSelectElement).value);
                  const status = (document.getElementById('editTaskStatus') as HTMLSelectElement).value;
                  const priority = (document.getElementById('editTaskPriority') as HTMLSelectElement).value;
                  const tags = (document.getElementById('editTaskTags') as HTMLInputElement).value;
                  
                  if (!title.trim()) {
                    alert('请输入任务标题');
                    return;
                  }
                  
                  try {
                    const res = await fetch(`/api/tasks/${editingTask.id}`, {
                      method: 'PUT',
                      headers: { 'Content-Type': 'application/json' },
                      body: JSON.stringify({ title, description, project_id, status, priority, tags })
                    });
                    const data = await res.json();
                    if (data.success) {
                      alert('任务更新成功');
                      setShowEditModal(false);
                      setEditingTask(null);
                      fetchTasks();
                    } else {
                      alert(data.error || '更新失败');
                    }
                  } catch (error) {
                    console.error('Failed to update task:', error);
                    alert('更新失败');
                  }
                }}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                保存修改
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 保存视图弹窗 */}
      {showSaveViewModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md">
            <h3 className="text-lg font-bold mb-4">保存视图</h3>
            <input
              type="text"
              value={viewName}
              onChange={(e) => setViewName(e.target.value)}
              placeholder="输入视图名称"
              className="w-full px-3 py-2 border border-gray-300 rounded-lg mb-4 focus:ring-2 focus:ring-blue-500"
              autoFocus
            />
            <div className="flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowSaveViewModal(false);
                  setViewName('');
                }}
                className="px-4 py-2 text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
              >
                取消
              </button>
              <button
                onClick={handleSaveView}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                保存
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Tasks;